WITH flattened AS (SELECT id, service, host, log_ts, level, latency_ms, key, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS key, value) SELECT id, host, level, latency_ms, key, value, MAX(latency_ms) OVER w_hist AS latency_ms_max_2h, RANK() OVER (ORDER BY latency_ms DESC NULLS LAST) AS latency_ms_rank FROM flattened WHERE log_ts >= '2023-11-01' WINDOW w_hist AS (ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW);
